/* @function terrainReference.clip — Inputs: camera and XYZ triangle/polygon. Returns near-plane-clipped polygon using the original arithmetic and camera coordinates; no source mutation. */
function clipTerrain(cam,poly){const depth=/* @function outdoor-assets.depth.12 — Returns p at 0 minus cam x multiplied by math sin using cam yaw plus p at 1 minus cam y multiplied by math cos using cam yaw multiplied by math cos using cam pitch plus p at 2 minus cam z multiplied by math sin using cam pitch. Inputs: p. Returns: p at 0 minus cam x multiplied by math sin using cam yaw plus p at 1 minus cam y multiplied by math cos using cam yaw multiplied by math cos using cam pitch plus p at 2 minus cam z multiplied by math sin using cam pitch. */ p=>((p[0]-cam.x)*Math.sin(cam.yaw)+(p[1]-cam.y)*Math.cos(cam.yaw))*Math.cos(cam.pitch)+(p[2]-cam.z)*Math.sin(cam.pitch),out=[];for(let i=0;i<poly.length;i++){const a=poly[i],b=poly[(i+1)%poly.length],da=depth(a),db=depth(b),inside=da>=.13;if(inside)out.push(a);if(inside!==(db>=.13)){const t=(.13-da)/(db-da);out.push(a.map(/* @function outdoor-assets.callback.13 — Returns v plus t multiplied by b at k minus v. Inputs: v; k. Returns: v plus t multiplied by b at k minus v. */ (v,k)=>v+t*(b[k]-v)));}}return out;}
